import { NgTemplateOutlet } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, contentChild, ElementRef, inject, input, model, NgModule, output, TemplateRef, viewChild, ViewEncapsulation } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { findSingle, uuid } from '@primeuix/utils';
import { MenuItem, SharedModule } from 'primeng/api';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { Menu, MenuModule } from 'primeng/menu';
import type {
    CommandMenuPassThrough,
    CommandMenuSearchChangeEvent,
    CommandMenuItemSelectEvent,
    CommandMenuItemTemplateContext,
    CommandMenuHeaderTemplateContext,
    CommandMenuFooterTemplateContext,
    CommandMenuEmptyMessageTemplateContext
} from 'primeng/types/commandmenu';
import { CommandMenuStyle } from './style/commandmenustyle';

/**
 * CommandMenu is a search-driven command palette component.
 * @group Components
 */
@Component({
    selector: 'p-commandmenu, p-command-menu',
    standalone: true,
    imports: [NgTemplateOutlet, MenuModule, SharedModule, BindModule],
    template: `
        <div [class]="cx('header')" [pBind]="ptm('header')">
            @if (headerTemplate()) {
                <ng-container *ngTemplateOutlet="headerTemplate(); context: { $implicit: search() }"></ng-container>
            }
            <input
                #searchInput
                type="text"
                role="combobox"
                [class]="cx('input')"
                [value]="search()"
                [placeholder]="placeholder()"
                [attr.aria-label]="ariaLabel()"
                [attr.aria-labelledby]="ariaLabelledBy()"
                [attr.aria-expanded]="true"
                [attr.aria-controls]="listId()"
                [attr.aria-activedescendant]="focusedOptionId()"
                autocomplete="off"
                autocorrect="off"
                spellcheck="false"
                (input)="onSearchInput($event)"
                (keydown)="onSearchKeyDown($event)"
                [pBind]="ptm('input')"
            />
        </div>

        <div [class]="cx('list')" [pBind]="ptm('list')">
            @if (hasVisibleItems()) {
                <p-menu #menu [model]="menuModel()" [tabindex]="-1" [style]="menuStyle()" [styleClass]="menuStyleClass()" [pt]="ptm('pcMenu')" [unstyled]="unstyled()">
                    @if (itemTemplate()) {
                        <ng-template #item let-item>
                            <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }"></ng-container>
                        </ng-template>
                    }
                </p-menu>
            } @else {
                <div [class]="cx('emptyMessage')" [pBind]="ptm('emptyMessage')">
                    @if (emptyMessageTemplate()) {
                        <ng-container *ngTemplateOutlet="emptyMessageTemplate(); context: { $implicit: search() }"></ng-container>
                    } @else {
                        {{ emptyMessageText() }}
                    }
                </div>
            }
        </div>

        @if (footerTemplate()) {
            <div [class]="cx('footer')" [pBind]="ptm('footer')">
                <ng-container *ngTemplateOutlet="footerTemplate(); context: { $implicit: search() }"></ng-container>
            </div>
        }
    `,
    providers: [CommandMenuStyle, { provide: PARENT_INSTANCE, useExisting: CommandMenu }],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    host: {
        '[attr.id]': '$id()',
        '[class]': "cx('root')"
    },
    hostDirectives: [Bind]
})
export class CommandMenu extends BaseComponent<CommandMenuPassThrough> {
    componentName = 'CommandMenu';

    bindDirectiveInstance = inject(Bind, { self: true });

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }

    /**
     * An array of menu items to display.
     * @group Props
     */
    model = input<MenuItem[]>();

    /**
     * Two-way bound search value.
     * @group Props
     */
    search = model<string>('');

    /**
     * Custom filter function. Receives (item, search) and returns a number (0 = no match).
     * @group Props
     */
    filter = input<(item: MenuItem, search: string) => number>();

    /**
     * Text to display when there are no results. Defaults to global value in i18n translation configuration.
     * @group Props
     */
    emptyMessage = input<string>();

    /**
     * Placeholder text for the search input.
     * @group Props
     */
    placeholder = input<string>();

    /**
     * Defines a string that labels the input for accessibility.
     * @group Props
     */
    ariaLabel = input<string>();

    /**
     * Identifies the element that labels the input for accessibility.
     * @group Props
     */
    ariaLabelledBy = input<string>();

    /**
     * Inline style of the menu.
     * @group Props
     */
    menuStyle = input<{ [klass: string]: any }>();

    /**
     * Style class of the menu.
     * @group Props
     */
    menuStyleClass = input<string>();

    /**
     * Callback to invoke when the search value changes.
     * @param {CommandMenuSearchChangeEvent} event - Custom search change event.
     * @group Emits
     */
    onSearchChange = output<CommandMenuSearchChangeEvent>();

    /**
     * Callback to invoke when a menu item is selected.
     * @param {CommandMenuItemSelectEvent} event - Custom item select event.
     * @group Emits
     */
    onSelect = output<CommandMenuItemSelectEvent>();

    /**
     * Custom item template.
     * @param {CommandMenuItemTemplateContext} context - item context.
     * @group Templates
     */
    itemTemplate = contentChild<TemplateRef<CommandMenuItemTemplateContext>>('item', { descendants: false });

    /**
     * Custom header template.
     * @param {CommandMenuHeaderTemplateContext} context - header context.
     * @group Templates
     */
    headerTemplate = contentChild<TemplateRef<CommandMenuHeaderTemplateContext>>('header', { descendants: false });

    /**
     * Custom footer template.
     * @param {CommandMenuFooterTemplateContext} context - footer context.
     * @group Templates
     */
    footerTemplate = contentChild<TemplateRef<CommandMenuFooterTemplateContext>>('footer', { descendants: false });

    /**
     * Custom empty message template.
     * @param {CommandMenuEmptyMessageTemplateContext} context - empty message context.
     * @group Templates
     */
    emptyMessageTemplate = contentChild<TemplateRef<CommandMenuEmptyMessageTemplateContext>>('emptyMessage', { descendants: false });

    menuViewChild = viewChild<Menu>('menu');

    searchInputViewChild = viewChild<ElementRef>('searchInput');

    _componentStyle = inject(CommandMenuStyle);

    private _internalId = uuid('pn_id_');

    $id = computed(() => this._internalId);

    listId = computed(() => `${this.$id()}_list`);

    private translation = toSignal(this.config.translationObserver, { initialValue: this.config.translation });

    emptyMessageText = computed(() => {
        return this.emptyMessage() || this.translation()?.emptyMessage || '';
    });

    focusedOptionId = computed(() => {
        const menu = this.menuViewChild();
        if (menu && menu.focusedOptionIndex() !== -1) {
            return menu.focusedOptionIndex();
        }
        return null;
    });

    /**
     * Filtered model: applies score-based filter with sorting by relevance.
     */
    filteredModel = computed((): MenuItem[] => {
        const searchVal = (this.search() ?? '').trim();
        const items = this.model() || [];

        if (!searchVal) return items;

        const filterFn = this.filter() ?? this.defaultFilter;

        return items
            .map((item: MenuItem) => {
                if (item.items?.length) {
                    const scored = item.items
                        .map((child: MenuItem) => ({
                            item: child,
                            score: filterFn(child, searchVal)
                        }))
                        .filter(({ score }) => score > 0)
                        .sort((a, b) => b.score - a.score);

                    if (scored.length === 0) return null;

                    return {
                        ...item,
                        items: scored.map((s) => s.item)
                    };
                } else if (!item.separator) {
                    const score = filterFn(item, searchVal);
                    return score > 0 ? item : null;
                }
                return null;
            })
            .filter(Boolean) as MenuItem[];
    });

    menuModel = computed((): MenuItem[] => {
        const wrap = (item: MenuItem): MenuItem => {
            if (item.items?.length) {
                return { ...item, items: item.items.map(wrap) };
            }
            if (item.separator) {
                return item;
            }
            const original = item.command;
            return {
                ...item,
                command: (event: any) => {
                    original?.(event);
                    this.onSelect.emit({ originalEvent: event?.originalEvent, item });
                }
            };
        };

        return this.filteredModel().map(wrap);
    });

    hasVisibleItems = computed(() => {
        const model = this.filteredModel();
        if (!model || model.length === 0) return false;
        return model.some((item) => (item.items?.length ?? 0) > 0 || (!item.separator && item.visible !== false));
    });

    onSearchKeyDown(event: KeyboardEvent) {
        const menu = this.menuViewChild();
        if (menu) {
            menu.onListKeyDown(event);

            const focusedId = menu.focusedOptionIndex();
            if (focusedId != null && focusedId !== -1) {
                requestAnimationFrame(() => {
                    const el = findSingle(menu.containerViewChild()?.nativeElement, `li[id="${focusedId}"]`) as HTMLElement | null;
                    el?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
                });
            }
        }
    }

    onSearchInput(event: Event) {
        const value = (event.target as HTMLInputElement).value;
        this.search.set(value);
        this.onSearchChange.emit({ originalEvent: event, query: value });
    }

    defaultFilter(item: MenuItem, search: string): number {
        const label = item.label ?? '';
        const keywords = (item as any).keywords;
        const extendValue = label + ' ' + (Array.isArray(keywords) ? keywords.join(' ') : '');

        if (extendValue.toLowerCase().includes(search.toLowerCase())) return 1;

        return 0;
    }

    focusInput() {
        this.searchInputViewChild()?.nativeElement?.focus();
    }
}

@NgModule({
    imports: [CommandMenu, SharedModule],
    exports: [CommandMenu, SharedModule]
})
export class CommandMenuModule {}
